<?php $s = row("SELECT s.*, c.name cb, u.name un FROM shifts s JOIN cashboxes c ON c.id=s.cashbox_id JOIN users u ON u.id=s.user_id WHERE s.id=?", [req_int('id')]); if (!$s) exit('یافت نشد');
$sum = $s['summary'] ? json_decode($s['summary'], true) : shift_expected((int)$s['id']); ?>
<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><title>گزارشِ شیفت</title><link rel="stylesheet" href="assets/print.css"><style>@page{size:80mm auto;margin:3mm}</style></head><body class="pp"><div class="rcpt"><h2>گزارشِ شیفتِ <?= fa_num($s['id']) ?></h2>
