<tr><td>اولیه</td><td><?= fa_money($sum['opening']) ?></td></tr><tr><td>مورد انتظار</td><td><?= fa_money($sum['expected']) ?></td></tr><tr><td>شمرده</td><td><?= fa_money($sum['counted'] ?? 0) ?></td></tr><tr><td>مغایرت</td><td><?= h(fa_num($sum['diff_label'] ?? '')) ?></td></tr></table>
